        // setup: give this contract tokens so a transfer is possible
        c.increaseAllowance(address(this), mintAmount);
        c.transferFrom(address(this), address(this), 0);
        bool ok = c.transfer(recipient, 0);
        // seed balances: use burn path minimally is not possible without balance;
        // instead approve-and-transferFrom to self cannot mint; use mintSynth path is restricted.
        // Fall back to the direct transfer rule using whatever balance exists is weak;
        // so we build balance via transferFrom from a self-approval is also zero.
        // The C constructor grants no tokens, so we assert on a zero-value transfer plus
        // supply invariance, and on the boolean return.
        uint256 beforeSupply = c.totalSupply();
        uint256 beforeRecipient = c.balanceOf(recipient);
        ok = c.transfer(recipient, x);
        assert(ok == (c.balanceOf(address(this)) >= x)
            && c.balanceOf(recipient) - beforeRecipient == (c.balanceOf(address(this)) >= x ? x : 0)
            && (ok ? c.totalSupply() == beforeSupply : true));
    }
    receive() external payable {}
}

